const searchAuditEvents = `-- name: SearchAuditEvents :many


SELECT id, actor_type, actor_id, action, target_type, target_id, reason, request_id, metadata, occurred_at, category, outcome FROM audit_events
WHERE (
    $1::timestamptz IS NULL
    OR (occurred_at, id) < ($1::timestamptz, $2::uuid)
  )
  AND ($3::text IS NULL OR category = $3)
  AND ($4::text IS NULL OR outcome = $4)
  AND ($5::text IS NULL OR actor_type = $5)
  AND ($6::text IS NULL OR actor_id = $6)
  AND ($7::text IS NULL OR action = $7)
  AND ($8::text IS NULL OR target_type = $8)
  AND ($9::text IS NULL OR target_id = $9)
  AND ($10::timestamptz IS NULL OR occurred_at >= $10)
  AND ($11::timestamptz IS NULL OR occurred_at < $11)
ORDER BY occurred_at DESC, id DESC
LIMIT $12
`

type SearchAuditEventsParams struct {
	CursorOccurredAt pgtype.Timestamptz `json:"cursor_occurred_at"`
	CursorID         pgtype.UUID        `json:"cursor_id"`
	Category         pgtype.Text        `json:"category"`
	Outcome          pgtype.Text        `json:"outcome"`
	ActorType        pgtype.Text        `json:"actor_type"`
	ActorID          pgtype.Text        `json:"actor_id"`
	Action           pgtype.Text        `json:"action"`
	TargetType       pgtype.Text        `json:"target_type"`
	TargetID         pgtype.Text        `json:"target_id"`
	OccurredFrom     pgtype.Timestamptz `json:"occurred_from"`
	OccurredTo       pgtype.Timestamptz `json:"occurred_to"`
	PageSize         int32              `json:"page_size"`
}

// ---------------------------------------------------------------------------
// Audit trail
// ---------------------------------------------------------------------------
// Audit events are written through `InsertAuditEvent` in commerce.sql, which is
// the single writer for the trail. The queries below only read it.
// Keyset pagination on (occurred_at, id) descending. Every filter is optional
// and null-tolerant, so the panel can compose them from URL state without
// building SQL on the client side.
func (q *Queries) SearchAuditEvents(ctx context.Context, arg SearchAuditEventsParams) ([]AuditEvent, error) {
	rows, err := q.db.Query(ctx, searchAuditEvents,
		arg.CursorOccurredAt,
		arg.CursorID,
		arg.Category,
		arg.Outcome,
		arg.ActorType,
		arg.ActorID,
		arg.Action,
		arg.TargetType,
		arg.TargetID,
		arg.OccurredFrom,
		arg.OccurredTo,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuditEvent{}
	for rows.Next() {
		var i AuditEvent
		if err := rows.Scan(
			&i.ID,
			&i.ActorType,
			&i.ActorID,
			&i.Action,
			&i.TargetType,
			&i.TargetID,
			&i.Reason,
			&i.RequestID,
			&i.Metadata,
			&i.OccurredAt,
			&i.Category,
			&i.Outcome,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchAuditEventsAscending = `-- name: SearchAuditEventsAscending :many
SELECT id, actor_type, actor_id, action, target_type, target_id, reason, request_id, metadata, occurred_at, category, outcome FROM audit_events
WHERE (
    $1::timestamptz IS NULL
    OR (occurred_at, id) > ($1::timestamptz, $2::uuid)
  )
  AND ($3::text IS NULL OR category = $3)
  AND ($4::text IS NULL OR outcome = $4)
  AND ($5::text IS NULL OR actor_type = $5)
  AND ($6::text IS NULL OR actor_id = $6)
  AND ($7::text IS NULL OR action = $7)
  AND ($8::text IS NULL OR target_type = $8)
  AND ($9::text IS NULL OR target_id = $9)
  AND ($10::timestamptz IS NULL OR occurred_at >= $10)
  AND ($11::timestamptz IS NULL OR occurred_at < $11)
ORDER BY occurred_at ASC, id ASC
LIMIT $12
`

type SearchAuditEventsAscendingParams struct {
	CursorOccurredAt pgtype.Timestamptz `json:"cursor_occurred_at"`
	CursorID         pgtype.UUID        `json:"cursor_id"`
	Category         pgtype.Text        `json:"category"`
	Outcome          pgtype.Text        `json:"outcome"`
	ActorType        pgtype.Text        `json:"actor_type"`
	ActorID          pgtype.Text        `json:"actor_id"`
	Action           pgtype.Text        `json:"action"`
	TargetType       pgtype.Text        `json:"target_type"`
	TargetID         pgtype.Text        `json:"target_id"`
	OccurredFrom     pgtype.Timestamptz `json:"occurred_from"`
	OccurredTo       pgtype.Timestamptz `json:"occurred_to"`
	PageSize         int32              `json:"page_size"`
}

// The oldest-first counterpart of SearchAuditEvents.
//
// Direction is a separate query rather than a CASE inside one, because a CASE
// in ORDER BY defeats the index and forces a sort of the whole matched set —
// on an append-only trail that grows without bound, that is the difference
// between an index scan and a full scan.
func (q *Queries) SearchAuditEventsAscending(ctx context.Context, arg SearchAuditEventsAscendingParams) ([]AuditEvent, error) {
	rows, err := q.db.Query(ctx, searchAuditEventsAscending,
		arg.CursorOccurredAt,
		arg.CursorID,
		arg.Category,
		arg.Outcome,
		arg.ActorType,
		arg.ActorID,
		arg.Action,
		arg.TargetType,
		arg.TargetID,
		arg.OccurredFrom,
		arg.OccurredTo,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AuditEvent{}
	for rows.Next() {
		var i AuditEvent
		if err := rows.Scan(
			&i.ID,
			&i.ActorType,
			&i.ActorID,
			&i.Action,
			&i.TargetType,
			&i.TargetID,
			&i.Reason,
			&i.RequestID,
			&i.Metadata,
			&i.OccurredAt,
			&i.Category,
			&i.Outcome,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

